function isErrorCode(value: string): value is ErrorCode {
  return Object.prototype.hasOwnProperty.call(ERROR_CATALOG, value);
}

export function resolveWireAlias(wireCode: string): ErrorCode | undefined {
  const trimmed = wireCode.trim().toLowerCase();
  if (!trimmed) {
    return undefined;
  }
  if (isErrorCode(trimmed)) {
    return trimmed;
  }
  return Object.prototype.hasOwnProperty.call(WIRE_ALIASES, trimmed)
    ? WIRE_ALIASES[trimmed]
    : undefined;
}

export function lookupErrorEntry(codeOrAlias: string): ErrorCatalogEntry | undefined {
  const canonical = resolveWireAlias(codeOrAlias);
  return canonical ? ERROR_CATALOG[canonical] : undefined;
}

export function resolveZhCnCopy(
  codeOrAlias: string,
  platform: ErrorPlatform = 'web',
): ErrorCopy | undefined {
  const entry = lookupErrorEntry(codeOrAlias);
  if (!entry) {
    return undefined;
  }
  if (platform === 'generic') {
    return entry.zhCn;
  }
  const override = entry.platformOverrides[platform];
  if (!override) {
    return entry.zhCn;
  }
  return {
    title: override.title ?? entry.zhCn.title,
    message: override.message ?? entry.zhCn.message,
    suggestion: override.suggestion ?? entry.zhCn.suggestion,
  };
}

export function formatErrorTemplate(
  template: string,
  params?: Readonly<Record<string, string | number>>,
): string {
  if (!params) {
    return template;
  }
  return template.replace(/\{([a-z][a-z0-9_]*)\}/g, (match, key: string) => {
    if (!Object.prototype.hasOwnProperty.call(params, key)) {
      return match;
    }
    const value = params[key];
    return value === undefined ? match : String(value);
  });
}

export interface BuildUiErrorOptions {
  readonly platform?: ErrorPlatform;
  readonly params?: Readonly<Record<string, string | number>>;
  readonly status?: number;
  readonly detail?: string;
}

export function buildUiError(
  codeOrAlias: string,
  options?: BuildUiErrorOptions,
): UiError {
  const platform = options?.platform ?? 'web';
  const entry = lookupErrorEntry(codeOrAlias) ?? ERROR_CATALOG[ERROR_CODES.COMMON_UNKNOWN];
  const copy = resolveZhCnCopy(entry.code, platform) ?? entry.zhCn;
  return {
    code: entry.code,
    title: formatErrorTemplate(copy.title, options?.params),
    message: formatErrorTemplate(copy.message, options?.params),
    suggestion: formatErrorTemplate(copy.suggestion, options?.params),
    severity: entry.severity,
    presentation: entry.presentation,
    action: entry.action,
    retryable: entry.retryable,
    ...(options?.status !== undefined ? { status: options.status } : {}),
    ...(options?.detail !== undefined ? { detail: options.detail } : {}),
  };
}
